SELECT * FROM user_role_relation WHERE user_id IN
#{item}
AND role_id IN ( SELECT id FROM user_role WHERE scope_id = 'global' )

select urr.id, u.id as userId, u.name, u.email, u.phone, u.wecom_userid as wecomUserid from user_role_relation urr inner join user u on u.id = urr.user_id and u.deleted = b'0' where urr.role_id = #{roleId} and urr.source_id = #{sourceId}
and (u.name like concat('%', #{keyword}, '%') or u.email like concat('%', #{keyword}, '%') or u.phone like concat('%', #{keyword}, '%') or u.wecom_userid like concat('%', #{keyword}, '%') or u.id like concat('%', #{keyword}, '%'))
order by urr.create_time desc

SELECT DISTINCT user_role_relation.role_id as id, user_role.`name` as name, user_role_relation.user_id as userId FROM user_role_relation LEFT JOIN user_role ON user_role_relation.role_id = user_role.id where user_role_relation.user_id in
#{item}
and organization_id = #{orgId} and source_id = #{orgId}

